package br.com.lealinfo.vidraceiro;
import android.os.*;import android.widget.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import org.json.*;
/** Same ViaCEP service already used by DeliveryAddress.LookupAsync in the PDV. Manual entry always remains available. */
final class CepLookup {
 static void bind(MainActivity a,EditText cep,EditText street,EditText district,EditText city,EditText uf,TextView status){Handler handler=new Handler(Looper.getMainLooper());final int[] revision={0};final Runnable[] pending={null};a.watch(cep,()->{int mine=++revision[0];if(pending[0]!=null)handler.removeCallbacks(pending[0]);String digits=cep.getText().toString().replaceAll("[^0-9]","");if(digits.length()!=8){status.setText("Digite o CEP com 8 dígitos. Endereço manual continua disponível.");return;}String[] before={street.getText().toString(),district.getText().toString(),city.getText().toString(),uf.getText().toString()};pending[0]=()->{status.setText("Localizando endereço…");Thread task=new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL("https://viacep.com.br/ws/"+digits+"/json/").openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(10000);JSONObject result;try{if(c.getResponseCode()!=200)throw new Exception();result=new JSONObject(new String(SyncTransport.read(c.getInputStream(),32000),StandardCharsets.UTF_8));}finally{c.disconnect();}if(result.optBoolean("erro")||result.optString("localidade").isEmpty()||result.optString("uf").length()!=2)throw new Exception();handler.post(()->{if(a.isFinishing()||a.isDestroyed()||mine!=revision[0])return;EditText[] fields={street,district,city,uf};String[] keys={"logradouro","bairro","localidade","uf"};for(int i=0;i<fields.length;i++)if(fields[i].getText().toString().equals(before[i]))fields[i].setText(result.optString(keys[i]));status.setText("CEP encontrado. Complete número/complemento; todos os campos continuam editáveis.");});}catch(Exception e){handler.post(()->{if(!a.isFinishing()&&!a.isDestroyed()&&mine==revision[0])status.setText("CEP indisponível. Preencha o endereço manualmente; o cadastro pode ser salvo.");});}},"AngraCep");task.setDaemon(true);task.start();};handler.postDelayed(pending[0],600);});}
 static String compose(String existing,EditText street,EditText number,EditText complement,EditText district,EditText city,EditText uf,EditText cep){String s=street.getText().toString().trim();if(s.isEmpty())return existing;return s+(number.getText().toString().trim().isEmpty()?"":", "+number.getText().toString().trim())+(complement.getText().toString().trim().isEmpty()?"":" • "+complement.getText().toString().trim())+(district.getText().toString().trim().isEmpty()?"":", "+district.getText().toString().trim())+(city.getText().toString().trim().isEmpty()?"":", "+city.getText().toString().trim())+(uf.getText().toString().trim().isEmpty()?"":" - "+uf.getText().toString().trim())+(cep.getText().toString().trim().isEmpty()?"":" • CEP "+cep.getText().toString().trim());}
}
